// biome-ignore lint/correctness/noUnusedImports: Storybook supports the classic JSX runtime.
import * as React from "react";
import { AgencySectionHeading } from "@/components/jabkit/agency-section-heading";
import { cn } from "@/lib/cn";
import { agencyIndexWorks } from "./AgencyIndexSection.mocks";
import type { AgencyIndexSectionProps } from "./AgencyIndexSection.types";

const defaults = {
  id: "index",
  number: "01",
  label: "Index",
  meta: "128 items",
  kicker: "[01] Independent design practice est. 2019",
  availability: "[05] BDX -- Berlin available Q3-Q4 2026",
  title: "Form follows friction",
  emphasis: "friction",
  body: "A graphic design practice working at the intersection of brand systems, editorial design, and screen-based typography. Built one grid at a time, with attention to the seams.",
  ctaLabel: "Browse index 128",
  ctaHref: "#works",
  categories: [
    "Brand systems",
    "Editorial design",
    "Web and interaction",
    "Print and packaging",
  ],
  worksHeading: "Selected works 2019-26",
} as const;

export function AgencyIndexSection({
  className,
  id = defaults.id,
  number = defaults.number,
  label = defaults.label,
  meta = defaults.meta,
  kicker = defaults.kicker,
  availability = defaults.availability,
  title = defaults.title,
  emphasis = defaults.emphasis,
  body = defaults.body,
  ctaLabel = defaults.ctaLabel,
  ctaHref = defaults.ctaHref,
  categories = [...defaults.categories],
  worksHeading = defaults.worksHeading,
  works = agencyIndexWorks,
  ...props
}: AgencyIndexSectionProps) {
  return (
    <section
      id={id}
      data-slot="agency-index-section"
      className={cn("bg-background text-foreground", className)}
      {...props}
    >
      <div className="mx-auto max-w-[90rem] px-[var(--jk-space-gutter)] pt-10 pb-16 sm:pt-14">
        <div className="flex flex-col gap-3 font-mono text-[11px] uppercase tracking-[0.16em] text-muted-foreground sm:flex-row sm:justify-between">
          <p>{kicker}</p>
          <p>{availability}</p>
        </div>
        <AgencySectionHeading
          className="mt-10"
          number={number}
          label={label}
          meta={meta}
          title={title}
          emphasis={emphasis}
          titleAs="h1"
        />
        <p className="mt-8 max-w-[62ch] text-base leading-relaxed text-muted-foreground">
          {body}
        </p>
        <a
          href={ctaHref}
          className="mt-8 inline-flex items-center gap-3 rounded-none bg-foreground px-5 py-3 font-mono text-[11px] tracking-[0.16em] text-background no-underline uppercase transition-[transform,background-color] duration-300 hover:bg-warning hover:text-warning-foreground motion-reduce:transition-none motion-reduce:hover:bg-foreground motion-reduce:hover:text-background"
        >
          {ctaLabel}
          <span aria-hidden="true">{">"}</span>
        </a>
      </div>
      <div className="bg-foreground px-[var(--jk-space-gutter)] py-4 text-background">
        <ul className="mx-auto flex max-w-[90rem] flex-wrap items-center gap-x-5 gap-y-2 font-mono text-[11px] uppercase tracking-[0.16em]">
          {categories.map((category, index) => (
            <li key={category} className="inline-flex items-center gap-5">
              {index > 0 ? (
                <span
                  aria-hidden="true"
                  className="size-1.5 rounded-full bg-warning"
                />
              ) : null}
              <span>{category}</span>
            </li>
          ))}
        </ul>
      </div>
      <div
        id="works"
        className="mx-auto max-w-[90rem] px-[var(--jk-space-gutter)] py-16"
      >
        <h2 className="font-[family-name:var(--jk-font-display)] text-2xl font-semibold tracking-tight text-foreground uppercase sm:text-4xl">
          {worksHeading}
        </h2>
        <ul className="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
          {works.map((work) => (
            <li key={work.href}>
              <a
                href={work.href}
                className="group block rounded-none no-underline"
              >
                <figure className="overflow-hidden bg-muted">
                  <img
                    src={work.image.src}
                    alt={work.image.alt}
                    className="aspect-[4/5] w-full object-cover transition-transform duration-500 ease-out group-hover:scale-[1.03] motion-reduce:transition-none motion-reduce:group-hover:scale-100"
                  />
                </figure>
                <p className="mt-2 font-mono text-[11px] tracking-[0.12em] text-foreground uppercase">
                  {work.title}
                </p>
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

import type { HTMLAttributes } from "react";

export interface AgencyIndexWork {
  title: string;
  href: string;
  image: {
    src: string;
    alt: string;
  };
}

export interface AgencyIndexSectionProps extends HTMLAttributes<HTMLElement> {
  id?: string;
  number?: string;
  label?: string;
  meta?: string;
  kicker?: string;
  availability?: string;
  title?: string;
  emphasis?: string;
  body?: string;
  ctaLabel?: string;
  ctaHref?: string;
  categories?: string[];
  worksHeading?: string;
  works?: AgencyIndexWork[];
}

import type {
  AgencyIndexSectionProps,
  AgencyIndexWork,
} from "./AgencyIndexSection.types";

export const agencyIndexWorks: AgencyIndexWork[] = [
  {
    title: "Atlas Type System",
    href: "#work-atlas",
    image: {
      src: "/assets/d7aec5a4066ae4f7.webp",
      alt: "Studio still for the Atlas type system",
    },
  },
  {
    title: "Harbor Review",
    href: "#work-harbor",
    image: {
      src: "/assets/42c22367c0be8e21.webp",
      alt: "Printed pages from Harbor Review",
    },
  },
  {
    title: "North Grid",
    href: "#work-north",
    image: {
      src: "/assets/47795ebdce09455e.webp",
      alt: "North Grid identity lockup on a table",
    },
  },
  {
    title: "Field Notes 26",
    href: "#work-field",
    image: {
      src: "/assets/63aeec58a6ab5c74.webp",
      alt: "Bound field notes on a desk",
    },
  },
  {
    title: "Signal Pack",
    href: "#work-signal",
    image: {
      src: "/assets/02a7269595e4f4e6.webp",
      alt: "Packaging sample from Signal Pack",
    },
  },
  {
    title: "River Marks",
    href: "#work-river",
    image: {
      src: "/assets/5267138413360745.webp",
      alt: "River Marks print specimens",
    },
  },
  {
    title: "Index Cards",
    href: "#work-cards",
    image: {
      src: "/assets/ec2b22380882848a.webp",
      alt: "Stacked index cards from a brand system",
    },
  },
  {
    title: "Screen Ledger",
    href: "#work-ledger",
    image: {
      src: "/assets/ece1ed59bb6c27ee.webp",
      alt: "Screen-based typography study",
    },
  },
];

export const agencyIndexSectionMocks = {
  default: {
    id: "index",
    number: "01",
    label: "Index",
    meta: "128 items",
    kicker: "[01] Independent design practice est. 2019",
    availability: "[05] BDX -- Berlin available Q3-Q4 2026",
    title: "Form follows friction",
    emphasis: "friction",
    body: "A graphic design practice working at the intersection of brand systems, editorial design, and screen-based typography. Built one grid at a time, with attention to the seams.",
    ctaLabel: "Browse index 128",
    ctaHref: "#works",
    categories: [
      "Brand systems",
      "Editorial design",
      "Web and interaction",
      "Print and packaging",
    ],
    worksHeading: "Selected works 2019-26",
    works: agencyIndexWorks,
  },
  alternate: {
    id: "index",
    number: "01",
    label: "Work",
    meta: "48 items",
    kicker: "[01] Studio practice est. 2021",
    availability: "[05] BER booking autumn 2026",
    title: "Type before decoration",
    emphasis: "decoration",
    body: "A smaller index of identity, print, and screen commissions for publishers and product teams.",
    ctaLabel: "Browse work 48",
    ctaHref: "#works",
    categories: ["Identity", "Print", "Screens"],
    worksHeading: "Selected works 2021-26",
    works: agencyIndexWorks.slice(0, 4),
  },
} satisfies Record<string, AgencyIndexSectionProps>;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...classes: ClassValue[]) {
  return twMerge(clsx(classes));
}
